/* Dragon Chase presentation. Flight owns targets, impacts, mastery and rewards. */
(()=>{'use strict';const api=window.DragonCinema={version:43},images={},bounds=new WeakMap();
 const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),mod=(n,d)=>((n%d)+d)%d,ready=im=>im?.complete&&im.naturalWidth>0;
 function load(key,src){const im=new Image();images[key]=im;im.onload=()=>{api[key+'Ready']=true};im.onerror=()=>api[key+'Error']=true;im.src=src;}
 load('fjord','art/fjord-v45.webp');load('flight','art/dragon-flight-v45.webp');load('rivals','art/rivals-v43.webp');
 function rect(im,cell){if(!bounds.has(im)){const c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(im,0,0);const data=cx.getImageData(0,0,c.width,c.height).data,cw=c.width/2,ch=c.height/2,rs=[];for(let n=0;n<4;n++){const ox=n%2*cw,oy=Math.floor(n/2)*ch;let l=cw,t=ch,r=0,b=0;for(let y=0;y<ch;y++)for(let x=0;x<cw;x++)if(data[((oy+y)*c.width+ox+x)*4+3]>120){l=Math.min(l,x);t=Math.min(t,y);r=Math.max(r,x);b=Math.max(b,y);}if(im===images.islands){const seen=new Uint8Array(cw*ch),queue=new Uint32Array(cw*ch);let best=0,box=null;for(let seed=0;seed<cw*ch;seed++){if(seen[seed])continue;seen[seed]=1;const sx=seed%cw,sy=Math.floor(seed/cw);if(data[((oy+sy)*c.width+ox+sx)*4+3]<220)continue;let head=0,tail=1,left=cw,top=ch,right=0,bottom=0;queue[0]=seed;while(head<tail){const q=queue[head++],x=q%cw,y=Math.floor(q/cw);left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);for(const next of [x>0?q-1:-1,x<cw-1?q+1:-1,y>0?q-cw:-1,y<ch-1?q+cw:-1]){if(next<0||seen[next])continue;seen[next]=1;const nx=next%cw,ny=Math.floor(next/cw);if(data[((oy+ny)*c.width+ox+nx)*4+3]>=220)queue[tail++]=next;}}if(tail>best){best=tail;box={left,top,right,bottom};}}if(box){l=Math.max(0,box.left-3);r=Math.min(cw-1,box.right+3);t=Math.max(0,box.top-3);b=Math.min(ch-1,box.bottom+3);}}rs.push({x:ox+l,y:oy+t,w:Math.max(1,r-l+1),h:Math.max(1,b-t+1)});}bounds.set(im,rs);}return bounds.get(im)[cell];}
 api.spriteRect=rect;
 function camera(s){const time=s.reduced?0:s.time,delta=(s.game?.targetX??.5)-(s.game?.x??.5);return{x:s.w*(.5+Math.sin(time*.11)*.035),y:s.h*(.34+Math.sin(time*.16)*.018),roll:s.reduced?0:clamp(delta*.13+Math.sin(time*.15)*.016,-.07,.07),f:Math.min(s.w*.95,s.h*1.4)};}
 function rotate(p,c){const x=p.x-c.x,y=p.y-c.y;return {...p,x:c.x+x*Math.cos(c.roll)-y*Math.sin(c.roll),y:c.y+x*Math.sin(c.roll)+y*Math.cos(c.roll)};}
 function worldPoint(s,x,y,z){const c=camera(s),depth=Math.max(5,z);return rotate({x:c.x+x*c.f/depth,y:c.y+(3-y)*c.f/depth,scale:c.f/depth},c);}
 function target(s,x,z,retainedPose=null){const enemy=retainedPose||s.game?.enemies.find(e=>Math.abs(e.x-x)<.001&&Math.abs(e.z-z)<.002),age=enemy?.age??1,side=enemy?.side||1,entry=1-clamp(age/.65,0,1),escape=clamp((enemy?.escapeAge||0)/.85,0,1),size=Math.min(s.w*.20,s.h*.24);return{x:s.w*(.5+(x-.5)*.95)+side*s.w*(entry+escape),y:s.h*(.38+(enemy?.id%3||0)*.035)-escape*s.h*.2,size,depth:40};}
 api.target=target;api.worldPoint=worldPoint;
 api.drawAccent=(s,x,y,size,skin='')=>{if(s.reduced)return;const key=String(skin||''),gold=key.includes('golden'),frost=key.includes('frostwing'),storm=key.includes('stormfire'),ember=key.includes('obsidian');if(!gold&&!frost&&!storm&&!ember)return;const ctx=s.ctx,color=gold?'#f8d98a':frost?'#b4efff':storm?'#bdb8fc':'#ff994e';ctx.save();ctx.strokeStyle=color;ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=gold?8:4;for(const side of [-1,1]){ctx.globalAlpha=gold?.4:.22;ctx.lineWidth=gold?1.4:.8;ctx.beginPath();for(let i=0;i<10;i++){const xx=x+side*size*(.34+i*.008)+Math.sin(s.time*2+i*.4)*size*.006,yy=y+size*(.05+i*.023);if(i)ctx.lineTo(xx,yy);else ctx.moveTo(xx,yy);}ctx.stroke();for(let i=0;i<(gold?8:4);i++){const q=mod(s.time*.38+i/8,1),px=x+side*size*(.30+q*.12)+Math.sin(i*13+s.time)*size*.012,py=y+size*(.10+q*.46);ctx.globalAlpha=(1-q)*(gold?.7:.45);ctx.beginPath();ctx.arc(px,py,(gold?1.6:1.1)*(1-q*.5),0,Math.PI*2);ctx.fill();}}ctx.restore();};
 function player(s,fromX=s.game?.x??.5){const gold=s.equippedDragon?.src?.includes('golden'),size=Math.min(s.w*(gold?.78:.72),s.h*(gold?.65:.62),gold?610:560),t=s.reduced?0:s.time;return{x:s.motion?clamp(s.w*(.5+s.motion.x*.034),size*.5+8,s.w-size*.5-8):s.w*(.23+.54*fromX),y:s.h*.76+(s.motion?s.motion.heave*size*.035:Math.sin(t*2.2)*size*.009),size,bank:s.reduced?0:s.motion?-s.motion.roll:clamp(((s.game?.targetX??.5)-(s.game?.x??.5))*.9,-.35,.35),mouthY:s.h*.76-size*.34};}
 api.player=player;
 function backdrop(s){const {ctx,w,h}=s,im=images.fjord;if(!ready(im)){ctx.fillStyle='#668b99';ctx.fillRect(0,0,w,h);return;}const scale=Math.max(w/im.naturalWidth,h/im.naturalHeight)*1.09,dw=im.naturalWidth*scale,dh=im.naturalHeight*scale,ox=(w-dw)/2+Math.sin(s.time*.10)*w*.014,oy=(h-dh)*.43;ctx.save();ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.filter='contrast(1.05) saturate(1.03)';ctx.drawImage(im,ox,oy,dw,dh);ctx.restore();const horizon=h*.53;ctx.save();ctx.beginPath();ctx.rect(0,horizon,w,h-horizon);ctx.clip();for(let i=0;i<36;i++){const q=i/36,yy=horizon+q*q*(h-horizon),sh=3+(h-horizon)/18*q;const sy=clamp((yy-oy)/scale,im.naturalHeight*.6,im.naturalHeight-10);ctx.globalAlpha=.35*q;ctx.drawImage(im,0,sy,im.naturalWidth,Math.max(1,sh/scale),ox+Math.sin(s.time*.7+i*.8)*q*3,yy,dw,sh);}ctx.restore();for(let i=0;i<26;i++){const q=mod(i/26+s.time*.12,1),z=q*q,x=w*.5+Math.sin(i*13)*w*.8*z;ctx.strokeStyle='#d4e6de';ctx.globalAlpha=z*.11;ctx.lineWidth=.5+z;ctx.beginPath();ctx.moveTo(x,horizon+z*(h-horizon));ctx.lineTo(x+z*17,horizon+z*(h-horizon)+z*2);ctx.stroke();}ctx.globalAlpha=1;}
 function scenery(s){const list=[],travel=s.time*18;
  for(let i=0;i<9;i++){const z=mod(55+i*41-travel,300)+10,side=i%2?1:-1,x=side*(13+i%3*5),y=-6-i%3*4,p=worldPoint(s,x,y,z);list.push({kind:'island',z,p,cell:i%4,width:p.scale*(10+i%3*3)});}
  return list.sort((a,b)=>b.z-a.z);
 }
 api.scenery=scenery;
 function island(s,b){const im=images.islands;if(!ready(im))return;const r=rect(im,b.cell),dw=b.width,dh=dw*r.h/r.w;if(b.p.x+dw*.6<0||b.p.x-dw*.6>s.w||b.p.y-dh*.2>s.h)return;s.ctx.save();s.ctx.globalAlpha=clamp((330-b.z)/120,.28,1);s.ctx.drawImage(im,r.x,r.y,r.w,r.h,b.p.x-dw/2,b.p.y-dh*.35,dw,dh);s.ctx.restore();}
 function clouds(s,front=false){const {ctx,w,h}=s,c=camera(s);for(let i=0;i<(s.reduced?3:9);i++){const distance=mod(35+i*29-s.time*13,240)+8;if(front?distance>24:distance<=24)continue;const side=i%2?1:-1,p=worldPoint(s,side*(6+i%3*5),-4-i%4,distance),r=clamp(p.scale*7,10,w*.7);ctx.save();ctx.globalAlpha=(front?.14:.24)*clamp((distance-8)/20,.2,1);const fog=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,r);fog.addColorStop(0,'#f3ffff');fog.addColorStop(.45,'#f4ffff88');fog.addColorStop(1,'#efffff00');ctx.fillStyle=fog;ctx.fillRect(p.x-r,p.y-r*.55,r*2,r*1.3);ctx.restore();}}
 function gate(s){const d=mod(90-s.time*18,220)+16,p=worldPoint(s,0,3,d),r=p.scale*7;if(r<10||r>s.w*1.3)return;const ctx=s.ctx;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(camera(s).roll);ctx.globalAlpha=.3;ctx.strokeStyle='#fff0b6';ctx.shadowColor='#ffe3a1';ctx.shadowBlur=12;ctx.lineWidth=clamp(p.scale*.05,1,5);ctx.beginPath();ctx.ellipse(0,0,r,r*.78,0,0,Math.PI*2);ctx.stroke();for(let i=0;i<12;i++){const a=i*Math.PI/6;ctx.fillStyle='#fff3bd';ctx.beginPath();ctx.arc(Math.cos(a)*r,Math.sin(a)*r*.78,clamp(p.scale*.12,1,5),0,Math.PI*2);ctx.fill();}ctx.restore();}
 // Wings hinge around their shoulders; the torso does not pulse with the wings.
 function dragon(s,im,cell,p,phase,bank=0){if(!ready(im))return;const r=rect(im,cell),ctx=s.ctx,size=p.size,dh=size*r.h/r.w,beat=s.reduced?0:Math.sin(phase),spread=.83+.17*(beat+1)/2;
  ctx.save();ctx.translate(p.x,p.y);ctx.rotate(bank);const draw=()=>ctx.drawImage(im,r.x,r.y,r.w,r.h,-size/2,-dh/2,size,dh);
  for(const side of [-1,1]){ctx.save();const hinge=side*size*.085;ctx.translate(hinge,-dh*.12);ctx.rotate(side*beat*.075);ctx.scale(spread,.96+beat*.035);ctx.translate(-hinge,dh*.12);ctx.beginPath();ctx.rect(side<0?-size*.55:size*.07,-dh*.6,size*.48,dh*1.2);ctx.clip();draw();ctx.restore();}
  ctx.save();ctx.beginPath();ctx.rect(-size*.095,-dh*.6,size*.19,dh*1.2);ctx.clip();draw();ctx.restore();ctx.restore();
 }
 function reticle(s,p,enemy){const ctx=s.ctx,r=p.size*.48;ctx.save();ctx.translate(p.x,p.y);ctx.strokeStyle=enemy.targeted?'#fff1a6':'#f5d0a375';ctx.lineWidth=enemy.targeted?2:1;for(let i=0;i<4;i++){ctx.save();ctx.rotate(i*Math.PI/2);ctx.beginPath();ctx.moveTo(-r*.2,-r);ctx.lineTo(-r,-r);ctx.lineTo(-r,-r*.2);ctx.stroke();ctx.restore();}if(enemy.targeted){ctx.font='900 '+clamp(s.w*.018,8,12)+'px system-ui';ctx.fillStyle='#fff2bc';ctx.textAlign='center';ctx.fillText('LOCKED',0,-r-7);}ctx.restore();}
 function rival(s,enemy){if(!enemy.targeted&&!enemy.escaping&&(s.game.ready||(enemy!==s.game.primary?.()&&s.game.charge!==3)))return;const p=target(s,enemy.x,enemy.z),im=ready(images.rivals)?images.rivals:s.dragon,cell=ready(images.rivals)?enemy.id%2*2:1;const bank=s.reduced?0:Math.sin(s.time*.9+enemy.id)*.10;dragon(s,im,cell,{...p,y:p.y},s.time*5.6+enemy.id,bank);reticle(s,p,enemy);}
 function flame(s,shot){const enemy=s.game?.enemies.find(e=>e.id===shot.targetId);if(!enemy)return;const {ctx}=s,start=player(s,shot.fromX),end=target(s,enemy.x,enemy.z);if(shot.miss){end.x+=shot.side*s.w*.45;end.y-=s.h*.15;}const t=clamp(shot.elapsed/shot.duration,0,1),at=q=>({x:start.x+(end.x-start.x)*q,y:start.mouthY+(end.y-start.mouthY)*q-Math.sin(q*Math.PI)*s.h*.035}),head=at(t),tail=at(Math.max(0,t-.28));ctx.save();ctx.globalCompositeOperation='screen';ctx.shadowColor='#ff9524';ctx.shadowBlur=shot.power?30:18;
  const fire=ctx.createLinearGradient(tail.x,tail.y,head.x,head.y);fire.addColorStop(0,'#ff582000');fire.addColorStop(.4,'#ff9133cc');fire.addColorStop(1,'#fff8c5');ctx.lineCap='round';ctx.lineWidth=shot.power?18:9;ctx.strokeStyle=fire;ctx.beginPath();ctx.moveTo(tail.x,tail.y);const mid=at(Math.max(0,t-.14));ctx.quadraticCurveTo(mid.x,mid.y,head.x,head.y);ctx.stroke();ctx.fillStyle='#fff8cc';ctx.beginPath();ctx.arc(head.x,head.y,shot.power?8:5,0,Math.PI*2);ctx.fill();for(let i=0;i<(s.reduced?3:12);i++){const q=clamp(t-i*.013,0,1),p=at(q);ctx.globalAlpha=1-i/13;ctx.fillStyle=i%2?'#ffb33c':'#fff1a2';ctx.beginPath();ctx.arc(p.x+Math.sin(s.time*20+i)*4,p.y+Math.cos(i*4+s.time*13)*4,(shot.power?4:2)*(1-i/15),0,Math.PI*2);ctx.fill();}ctx.restore();}
 function impacts(s){const {ctx}=s;for(const f of s.particles){if(!s.paused){f.x+=f.vx*s.dt;f.y+=f.vy*s.dt;f.life-=s.dt;}if(f.life<=0)continue;ctx.save();ctx.globalAlpha=f.life;ctx.fillStyle=f.color;ctx.shadowColor=f.color;ctx.shadowBlur=7;ctx.beginPath();ctx.arc(f.x,f.y,2+f.life*3,0,Math.PI*2);ctx.fill();ctx.restore();}for(const ring of s.rings){if(!s.paused)ring.life-=s.dt;if(ring.life<=0)continue;const p=ring.point?{x:ring.point.x*s.w,y:ring.point.y*s.h}:target(s,ring.x,ring.z,ring.pose),r=(1-ring.life)*(ring.power?90:60)+10;ctx.save();ctx.globalAlpha=ring.life;ctx.strokeStyle=ring.power?'#fff5b0':'#ffda80';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.stroke();ctx.font='900 '+clamp(s.w*.04,14,23)+'px system-ui';ctx.fillStyle='#fff8d5';ctx.textAlign='center';ctx.fillText(ring.power?'+50':'+25',p.x,p.y-r*.3);ctx.restore();}}
 api.draw=s=>{if(!s.ctx||s.w<1||s.h<1)return false;const v=s.reduced?{...s,time:0}:s;const ctx=s.ctx;ctx.save();ctx.save();ctx.translate(s.w/2,s.h/2);ctx.rotate((s.motion?.roll||0)*.08);ctx.translate(-s.w/2,-s.h/2);backdrop(v);ctx.restore();for(const e of [...(s.game?.enemies||[])].sort((a,b)=>a.z-b.z))rival(v,e);for(const shot of s.game?.shots||[])flame(v,shot);const hero=player(v),image=ready(s.equippedDragon)?s.equippedDragon:ready(images.flight)?images.flight:s.dragon;const ending=!s.reduced&&s.victoryFlight>=0?clamp(s.victoryFlight/4,0,1):0,ease=ending*ending*(3-2*ending),flightHero={...hero,x:hero.x+(s.w*.5-hero.x)*ease,y:hero.y+(s.h*.34-hero.y)*ease,size:hero.size*(1-ease*.65)};api.drawAccent?.(v,flightHero.x,flightHero.y,flightHero.size,s.equippedDragon?.src);dragon(v,image,image===images.flight?0:1,flightHero,s.time*5.8,hero.bank*(1-ease));impacts(s);
  if(s.power>0){ctx.strokeStyle='#ffe09c88';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(hero.x,hero.y,hero.size*.4,hero.size*.15,-s.time*.7,0,Math.PI*2);ctx.stroke();}if(s.flash>0){ctx.globalAlpha=s.flash*.16;ctx.fillStyle='#ffbd9b';ctx.fillRect(0,0,s.w,s.h);ctx.globalAlpha=1;}if(s.paused&&s.game?.active){ctx.fillStyle='#123b5766';ctx.fillRect(0,0,s.w,s.h);ctx.fillStyle='#fff5d1';ctx.font='900 24px system-ui';ctx.textAlign='center';ctx.fillText('FLIGHT PAUSED',s.w/2,s.h*.5);}ctx.restore();s.canvas.dataset.renderer='fjord-flight-compatible';s.canvas.dataset.flight='forward';s.canvas.dataset.skin=ready(s.equippedDragon)?'equipped':'original';return true;};
})();
